#!/usr/bin/env python3
import os

# gather code files (excluding tests/, venv, __init__.py, and test_*.py)
code_files = []
for root, dirs, files in os.walk('.'):
    # skip venv directories and tests directory itself
    parts = root.split(os.sep)
    if 'venv' in parts or 'tests/venv' in root:
        continue
    if root.startswith('./tests'):
        continue
    for f in files:
        if f.endswith('.py') and not f.startswith('test_') and f != '__init__.py':
            code_files.append(os.path.join(root, f))

# gather test files (test_*.py)
test_files = []
for root, dirs, files in os.walk('.'):
    if 'venv' in root.split(os.sep):
        continue
    for f in files:
        if f.startswith('test_') and f.endswith('.py'):
            test_files.append(os.path.join(root, f))

# determine tested module basenames
tested = set()
for t in test_files:
    base = os.path.basename(t)
    if base.startswith('test_'):
        tested.add(os.path.splitext(base)[0][5:])

# find missing tests
missing = []
for f in code_files:
    name = os.path.splitext(os.path.basename(f))[0]
    if name not in tested:
        missing.append(f)

# sort missing by file size descending
missing.sort(key=lambda f: -os.path.getsize(f))

# write output file
with open('no_text_coverage.txt', 'w') as out:
    for f in missing:
        out.write(f.lstrip('./') + '\n')
